import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { CashBankBalanceRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './SoDuQuyNganHangPage.module.css';

const TEST_ID = 'rpt-so-du-quy-ngan-hang';
const PAGE_ID = 'baocao-so-du-quy-ngan-hang';
const TITLE = 'Báo cáo số dư tại quỹ và tại các ngân hàng';

type RowTag = 'Leaf' | 'Parent' | 'Total';

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function todayIso(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function mapRowTag(raw: CashBankBalanceRow['rowTag'], isTotal?: boolean, isParent?: boolean): RowTag {
  if (raw === 'Total' || isTotal) return 'Total';
  if (raw === 'Parent' || isParent) return 'Parent';
  return 'Leaf';
}

function normalizeItems(items: CashBankBalanceRow[]): CashBankBalanceRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isTotal, r.isParent);
    const isTotal = rowTag === 'Total' || Boolean(r.isTotal);
    const isParent = rowTag === 'Parent' || Boolean(r.isParent);
    return {
      ...r,
      rowTag,
      isTotal,
      isParent,
      isBold: Boolean(r.isBold) || isTotal || isParent,
      accountCode: r.accountCode ?? '',
      accountCodeDisplay: r.accountCodeDisplay ?? '',
      accountName: r.accountName ?? '',
      accountLevel: Number(r.accountLevel ?? 0),
      balance: Number(r.balance ?? 0),
    };
  });
}

function rowClass(tag: RowTag): string {
  if (tag === 'Total') return styles.rowToneTotal;
  if (tag === 'Parent') return styles.rowToneParent;
  return styles.rowToneLeaf;
}

const SoDuQuyNganHangPage: React.FC = () => {
  const dispatch = useAppDispatch();

  const [accountCode, setAccountCode] = useState('111');
  const [asOfDate, setAsOfDate] = useState(todayIso());

  const [items, setItems] = useState<CashBankBalanceRow[]>([]);
  const [appliedAsOf, setAppliedAsOf] = useState('');
  const [appliedAccount, setAppliedAccount] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const summary = useMemo(() => {
    if (!hasViewed) return null;
    const total = items.find(r => mapRowTag(r.rowTag, r.isTotal, r.isParent) === 'Total');
    if (!total) return null;
    return { balance: Number(total.balance ?? 0) };
  }, [hasViewed, items]);

  const leafCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isTotal, r.isParent) === 'Leaf').length,
    [items],
  );

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    const asOf = asOfDate.trim();
    if (!asOf) {
      setFilterError('Chọn ngày số dư');
      dispatchAppToast(dispatch, { message: 'Chọn ngày số dư', type: 'error' });
      return;
    }
    // Empty TK → normalize 111 (parity token #111). Cấm silent empty→all.
    const acct = accountCode.trim() || '111';
    if (!accountCode.trim()) {
      setAccountCode('111');
    }

    setLoading(true);
    analyticsService
      .getCashBankBalances({
        asOfDate: asOf,
        accountCode: acct,
        pageSize: 0,
      })
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setAppliedAsOf(asOf);
        setAppliedAccount(acct);
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được báo cáo số dư quỹ/NH'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [accountCode, asOfDate, dispatch]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    setAccountCode('111');
    setAsOfDate(todayIso());
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedAccount || !appliedAsOf) return;
    const fileName = `so-du-quy-ngan-hang_${appliedAccount}_${appliedAsOf}.xlsx`;
    void exportExcel(
      '/accounting/cash-bank-balances/export-excel',
      {
        accountCode: appliedAccount,
        asOfDate: appliedAsOf,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedAccount, appliedAsOf, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const exportDisabled = !hasViewed || loading || !appliedAccount;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedAsOf
      ? `Ngày: ${formatDate(appliedAsOf)}`
      : undefined;

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div data-testid={`${TEST_ID}-subtitle`} className={reportStyles.subtitle} style={{ marginBottom: '0.5rem' }}>
          {subtitle}
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Tài khoản</th>
            <th>Tên tài khoản</th>
            <th className={reportStyles.colRight}>Số dư</th>
          </tr>
        </thead>
        <tbody>
          {!hasViewed
            ? null
            : items.map((row, index) => {
                const tag = mapRowTag(row.rowTag, row.isTotal, row.isParent);
                const isTotal = tag === 'Total';
                const isParent = tag === 'Parent';
                return (
                  <tr
                    key={`${tag}|${row.accountCode ?? 'T'}|${isParent ? 'P' : 'L'}|${index}`}
                    className={rowClass(tag)}
                    data-testid={`${TEST_ID}-row-${index}`}
                    data-row-tag={tag}
                    data-is-parent={isParent ? '1' : '0'}
                    data-is-total={isTotal ? '1' : '0'}
                    data-account-code={row.accountCode ?? ''}
                    data-drillable="0"
                  >
                    <td className={styles.cellIndent}>{isTotal ? '' : (row.accountCodeDisplay ?? row.accountCode ?? '')}</td>
                    <td>{row.accountName ?? ''}</td>
                    <td className={reportStyles.colRight}>{formatVnd(row.balance ?? 0)}</td>
                  </tr>
                );
              })}
        </tbody>
      </table>
      {hasViewed && leafCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summary ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        <span>Số dư: {formatVnd(summary.balance)}</span>
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-university' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-accountCode`}>
              <Input
                label="Tài khoản"
                value={accountCode}
                onChange={e => setAccountCode(e.target.value)}
                onKeyDown={onEnterView}
                placeholder="111"
                data-testid={`${TEST_ID}-field-account`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-asOfDate`}>
              <Input
                type="date"
                label="Ngày số dư"
                value={asOfDate}
                onChange={e => setAsOfDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-asOf`}
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default SoDuQuyNganHangPage;
